ST.xhtml:
(* ---- stop: drop to safe state (Z up, X stop, vacuum off) ---- *)
IF stop_btn THEN
    running := FALSE;
END_IF;

IF NOT running THEN
    x_fwd := FALSE; x_rev := FALSE;
    z_down_cmd := FALSE; vacuum := FALSE;
    step_no := 0;
    (* start only from home with Z up *)
    IF start_btn AND x_home AND z_up THEN
        running := TRUE;
        step_no := 1;
    END_IF;
ELSE
    (* ---- 8-step pick&place cycle; motion-safety: X axes move only while Z is up ---- *)
    CASE step_no OF
        1:  (* X: home -> pick *)
            IF z_up THEN x_fwd := TRUE; END_IF;
            IF x_pick THEN x_fwd := FALSE; step_no := 2; END_IF;
        2:  (* Z down at pick, grab if part present *)
            IF NOT z_dn THEN z_down_cmd := TRUE; END_IF;
            IF z_dn THEN
                IF part_det THEN
                    vacuum := TRUE;
                    step_no := 3;
                ELSE
                    step_no := 9;      (* no part: abort pick, wait at safe height *)
                END_IF;
            END_IF;
        3:  (* Z up with part *)
            z_down_cmd := FALSE;
            IF z_up THEN step_no := 4; END_IF;
        4:  (* X: pick -> place *)
            IF z_up THEN x_fwd := TRUE; END_IF;
            IF x_place THEN x_fwd := FALSE; step_no := 5; END_IF;
        5:  (* Z down at place, release *)
            z_down_cmd := TRUE;
            IF z_dn THEN
                vacuum := FALSE;
                placed_cnt := placed_cnt + 1;
                step_no := 6;
            END_IF;
        6:  (* Z up *)
            z_down_cmd := FALSE;
            IF z_up THEN step_no := 7; END_IF;
        7:  (* X: place -> home *)
            IF z_up THEN x_rev := TRUE; END_IF;
            IF x_home THEN x_rev := FALSE; step_no := 1; END_IF;
        9:  (* no-part wait: lift Z first, then wait for part at pick *)
            z_down_cmd := FALSE;
            IF z_up AND part_det THEN step_no := 2; END_IF;
    END_CASE;
END_IF;
